const b64="";Deno.serve((req)=>{if(req.method!=="GET")return new Response("Method not allowed",{status:405});const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));return new Response(bytes,{headers:{"Content-Type":"image/png","Cache-Control":"public, max-age=86400","X-Content-Type-Options":"nosniff"}})});
